"""Commands generated by RouteManager, without touching the network."""

from __future__ import annotations

import subprocess
import unittest

from antilag.net.discovery import Link
from antilag.net.routes import RouteManager

GAME = ("100.25.151.1/32", "172.65.219.118/32")

LINKS = [
    Link(name="Ethernet", address="10.0.0.5", gateway="10.0.0.1", index=12, metric=25),
    Link(name="Wi-Fi", address="10.47.197.115", gateway="10.47.197.217", index=7, metric=35),
    Link(name="sin-gw", address="192.0.2.9", index=3),
]


class Recorder:
    def __init__(self) -> None:
        self.calls: list[list[str]] = []

    def __call__(self, argv, check=True):
        self.calls.append(argv)
        return subprocess.CompletedProcess(argv, 0, "", "")


class TestWindows(unittest.TestCase):
    def setUp(self):
        self.run = Recorder()
        self.routes = RouteManager(platform="win32", runner=self.run)
        self.routes.setup("antilag", 42, "10.66.0.2/24", 1400, GAME, "3.4.5.6", LINKS)

    def joined(self):
        return [" ".join(c) for c in self.run.calls]

    def test_tun_address_and_mtu_are_volatile(self):
        calls = self.joined()
        self.assertIn(
            "netsh interface ipv4 set address name=42 source=static address=10.66.0.2 "
            "mask=255.255.255.0 store=active", calls)
        self.assertIn("netsh interface ipv4 set subinterface 42 mtu=1400 store=active", calls)

    def test_world_ips_through_tun(self):
        calls = self.joined()
        for prefix in GAME:
            self.assertIn(f"netsh interface ipv4 add route {prefix} 42 metric=1 store=active", calls)

    def test_server_pinned_to_each_physical_gateway(self):
        calls = self.joined()
        self.assertIn(
            "netsh interface ipv4 add route 3.4.5.6/32 12 10.0.0.1 metric=25 store=active", calls)
        self.assertIn(
            "netsh interface ipv4 add route 3.4.5.6/32 7 10.47.197.217 metric=36 store=active", calls)
        self.assertFalse(any("3.4.5.6/32 3 " in c for c in calls), "sin gateway no hay ruta")

    def test_close_removes_what_was_added(self):
        added = len([c for c in self.run.calls if c[3:5] == ["add", "route"]])
        self.run.calls.clear()
        self.routes.close()
        deletes = [c for c in self.run.calls if c[3:5] == ["delete", "route"]]
        self.assertEqual(len(deletes), added)
        self.routes.close()  # idempotent
        self.assertEqual(len([c for c in self.run.calls if c[3:5] == ["delete", "route"]]), added)


class TestLinux(unittest.TestCase):
    def test_commands(self):
        run = Recorder()
        routes = RouteManager(platform="linux", runner=run)
        routes.setup("antilag", None, "10.66.0.2/24", 1400, GAME, "3.4.5.6", LINKS[:1])
        calls = [" ".join(c) for c in run.calls]
        self.assertIn("ip addr replace 10.66.0.2/24 dev antilag", calls)
        self.assertIn("ip route replace 3.4.5.6/32 via 10.0.0.1 dev Ethernet metric 25", calls)
        self.assertIn("ip route replace 100.25.151.1/32 dev antilag metric 1", calls)


if __name__ == "__main__":
    unittest.main()
